import{_ as o,o as t,c as r,a2 as c}from"./chunks/framework.BM5YPQmL.js";const _=JSON.parse('{"title":"NIC and wireless drivers","description":"","frontmatter":{},"headers":[],"relativePath":"l1/driver-nic.md","filePath":"l1/driver-nic.md"}'),a={name:"l1/driver-nic.md"};function s(d,e,i,l,n,h){return t(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="nic-and-wireless-drivers" tabindex="-1">NIC and wireless drivers <a class="header-anchor" href="#nic-and-wireless-drivers" aria-label="Permalink to &quot;NIC and wireless drivers&quot;">​</a></h1><p>How a network family joins the net service.</p><h2 id="the-model-3-0-0" tabindex="-1">The model (3.0.0) <a class="header-anchor" href="#the-model-3-0-0" aria-label="Permalink to &quot;The model (3.0.0)&quot;">​</a></h2><ul><li>Drivers live in <code>ocos/drivers/net/</code> - one file per family (<code>drv_net_e1000e.c</code>, <code>drv_net_igb.c</code>, <code>drv_net_ixgbe.c</code>, <code>drv_net_rtl8139.c</code>, <code>drv_net_rtl8169.c</code>, <code>drv_net_bcm57xx.c</code>, <code>drv_net_other.c</code>), plus the wireless stack (<code>drv_net_wireless.c</code>, <code>drv_net_ath.c</code>, <code>drv_net_brcm.c</code>, <code>drv_net_iwlwifi.c</code>, <code>drv_net_rtlwifi.c</code>).</li><li>Identity: <code>OC_DRIVER_DECL(&quot;nic&quot;, &quot;e1000e&quot;, &amp;ops, &quot;Intel e1000e&quot;)</code><ul><li>or the <code>&quot;wireless&quot;</code> class for 802.11 families. The boot collector probes; families self-report honest states (registered / scanning / connected).</li></ul></li><li>The driver-internal table API is <code>drv_net_api.h</code> - kernel internal, mutated only from the family&#39;s own probe paths.</li><li>The net service (<code>ocos/services/net/</code>) owns the stack: IPv4 + TCP/UDP, DHCP, DNS, the firewall/netfilter, TLS, SSH/sshd, and the L1SVC category 3/8 surfaces.</li></ul><h2 id="the-wireless-layer" tabindex="-1">The wireless layer <a class="header-anchor" href="#the-wireless-layer" aria-label="Permalink to &quot;The wireless layer&quot;">​</a></h2><p><code>wifi</code> (status / scan / test / sdio) reports per-family state and beacon-derived scan lists; <code>bt</code> (status / usb / uart / test) fronts the Bluetooth transports (HCI-USB in <code>drv_misc_bt_usb.c</code>, H4 UART, the full L2CAP/SDP/RFCOMM/SPP chain). No hardware -&gt; the honest &quot;no wireless devices registered&quot; line, never a fake list.</p><h2 id="what-a-new-family-looks-like" tabindex="-1">What a new family looks like <a class="header-anchor" href="#what-a-new-family-looks-like" aria-label="Permalink to &quot;What a new family looks like&quot;">​</a></h2><ol><li><code>ocos/drivers/net/drv_net_&lt;fam&gt;.{c,h}</code> - PCI probe, MAC setup, RX/TX into the service&#39;s packet path.</li><li><code>OC_DRIVER_DECL(&quot;nic&quot;, &quot;&lt;fam&gt;&quot;, &amp;ops, &quot;description&quot;)</code>.</li><li>Optional status/test op: APPEND the number in <code>svc_sysapi_l1svc.h</code>, regenerate the mirror, add the classic table row (<code>net-tool</code>&#39;s <code>g_ops[]</code>) or a thin wrapper folder.</li></ol><h2 id="the-consumer-contract" tabindex="-1">The consumer contract <a class="header-anchor" href="#the-consumer-contract" aria-label="Permalink to &quot;The consumer contract&quot;">​</a></h2><p>Apps call the service, never drivers: <code>net-tool ip</code> -&gt; <code>sys_l1svc(NET, IP, ...)</code>; <code>ping</code>/<code>wget</code> ride the <code>SYS_NETCMD</code> bridge (op 2 / 4). The output lines (<code>&quot;IP: ...&quot;</code>, <code>&quot;DHCP success: IP=...&quot;</code>, <code>&quot;DNS resolution failed (timeout)&quot;</code>) are the anchors the update wizard and the docs rely on - see <a href="./surface-map.html">surface-map.md</a>.</p>',10)])])}const p=o(a,[["render",s]]);export{_ as __pageData,p as default};
